
async function discoverAuthenticatedSessions(){const deadline=Date.now()+12000;while(Date.now()<deadline){const el=[...document.querySelectorAll('[aria-label]')].find(e=>/Google Account:/i.test(e.getAttribute('aria-label')||''));const label=el?.getAttribute('aria-label')||'';const match=label.match(/Google Account:\s*(.*?)\s*\(([^)]+@[^)]+)\)/is);if(match){const email=match[2].trim();return [{id:email,label:match[1].trim()+' ('+email+')',url:"https://aistudio.google.com/spend"}];}if(location.hostname==='accounts.google.com')return [];await new Promise(r=>setTimeout(r,200));}throw Error('Google account identity unavailable; refusing to infer authentication from page presence');}
async function assertSelectedAccount(context){const list=await discoverAuthenticatedSessions();if(!context?.session||!list.some(s=>s.id===context.session.id))throw Error('Selected account is unavailable or changed; rediscover sessions');}
const clean=v=>String(v??'').replace(/\s+/g,' ').trim();
const wait=async(f)=>{const end=Date.now()+18000;while(Date.now()<end){const v=f();if(v)return v;await new Promise(r=>setTimeout(r,200));}throw new Error('Page did not reach expected state; no automatic mutation retry.');};
const button=t=>Array.from(document.querySelectorAll('button')).find(e=>clean(e.innerText)===t);
async function chooseProject(name){await wait(()=>document.querySelector('[role=combobox]'));let s=document.querySelector('[role=combobox]');if(clean(s.innerText)!==name){s.click();const o=await wait(()=>Array.from(document.querySelectorAll('[role=option]')).find(e=>clean(e.innerText)===name));o.click();}await wait(()=>clean(document.querySelector('[role=combobox]')?.innerText)===name&&button('Edit spend cap'));}
function spend(name){if(clean(document.querySelector('[role=combobox]')?.innerText)!==name)throw new Error('Project mismatch');const text=document.body.innerText;const m=text.match(/Edit spend cap\s*\$([\d,.]+)\s*\/\s*\$([\d,.]+)/);if(!m)throw new Error('Spending values unavailable or unexpected page');return {project:name,spent:Number(m[1].replaceAll(',','')),monthlyCap:Number(m[2].replaceAll(',','')),currency:'USD',prepayWarning:text.includes('required to switch to prepay')};}
window.ox.install(({ action: registerAction }) => {
const protectedActionIds=new Set(["listProjects","getSpend","setMonthlySpendCap"]);
const action=(id,handler)=>registerAction(id,protectedActionIds.has(id)?{...handler,async invoke(args,context){await assertSelectedAccount(context);return handler.invoke(args,context);}}:handler);
action('listSessions',{async invoke(){return discoverAuthenticatedSessions();}});
action('login',{async invoke(){return null;}});
action('listProjects',{async invoke(){const rows=await wait(()=>{const r=Array.from(document.querySelectorAll('tr,[role=row]')).filter(e=>/key|Create API key/.test(e.innerText)&&!e.innerText.includes('Monthly Spend'));return r.length&&r.every(e=>clean(e.querySelectorAll('td,[role=cell]')[4]?.innerText))?r:null;});return {items:rows.map(r=>{const c=Array.from(r.querySelectorAll('td,[role=cell]')).map(e=>clean(e.innerText));if(c.length<5)throw new Error('Unexpected project table');return {name:clean(r.querySelector('td,[role=cell]')?.innerText.split('\n')[0]),keyStatus:c[1],billingStatus:c.slice(4,6).join(' ')};}),nextCursor:null};}});
action('getSpend',{async invoke(a){await chooseProject(a.project);return await wait(()=>{try{return spend(a.project)}catch{return null}});}});
action('setMonthlySpendCap',{async invoke(a){if(!(typeof a.amount==='number'&&Number.isFinite(a.amount)&&a.amount>0&&a.amount<=100000))throw new Error('Invalid spending cap');await chooseProject(a.project);const before=await wait(()=>{try{return spend(a.project)}catch{return null}});if(before.monthlyCap===a.amount)return before;button('Edit spend cap').click();const i=await wait(()=>Array.from(document.querySelectorAll('input')).find(e=>e.getAttribute('aria-label')==='Monthly spend cap'));i.value=String(a.amount);i.dispatchEvent(new Event('input',{bubbles:true}));i.dispatchEvent(new Event('change',{bubbles:true}));const b=button('Save');if(!b||b.disabled)throw new Error('Save unavailable');b.click();return await wait(()=>{try{const s=spend(a.project);return s.monthlyCap===a.amount?s:null}catch{return null}});}});
});